package main

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"
)

func TestProbeHealthzGating(t *testing.T) {
	store := NewStore(time.Minute)
	store.Create("a", "u")
	handler := healthHandler(store)

	rec := httptest.NewRecorder()
	handler(rec, httptest.NewRequest("GET", "/healthz", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("healthz status = %d, want 200", rec.Code)
	}
	var body map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
		t.Fatalf("body not json: %v", err)
	}
	if _, present := body["sessions"]; present {
		t.Fatalf("session count leaked without admin flag: %v", body)
	}

	rec = httptest.NewRecorder()
	handler(rec, httptest.NewRequest("GET", "/healthz?admin=1", nil))
	body = map[string]any{}
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
		t.Fatalf("admin body not json: %v", err)
	}
	if body["sessions"] != float64(1) {
		t.Fatalf("admin sessions = %v, want 1", body["sessions"])
	}
}
EOF
go test -count=1 . ; rc=$? ; rm -f probe_healthz_test.go ; exit $rc

